    $('#class-location').hidden=!classStep;$('#class-step-label').textContent=classStep?`The class is on ${getStage(room.stage)?.title||room.stage}. Your current work is saved.`:'';
    $('#join-current').disabled=!classStep||!permitted(room?.stage)||running;
