    const previewLabel=document.createElement('label');previewLabel.htmlFor='response-preview';previewLabel.textContent='Show in each card';const previewChoice=document.createElement('select');previewChoice.id='response-preview';previewChoice.innerHTML='<option value="auto">Best available response</option><option value="answers">Written responses</option><option value="code">Python code</option><option value="output">Actual run output</option>';previewChoice.value=responsePreview;previewChoice.onchange=e=>{responsePreview=e.target.value;renderRoster();};$('#class-overview .response-options').append(previewLabel,previewChoice);
    const options=$('#class-overview .response-options'),settings=document.createElement('details'),settingsTitle=document.createElement('summary');settings.className='response-settings';settingsTitle.textContent='Response view options';options.before(settings);settings.append(settingsTitle,options);$('#teacher-board > p.small').textContent='Private — do not screen-share. Saved responses, not live typing.';
    $('#share-safe-toggle').onclick=()=>setShareSafe(true);$('#exit-share-safe').onclick=()=>setShareSafe(false);
    $('#end-class').onclick=()=>{if(confirm('End live work? Students keep their drafts and can export evidence.')){demoVersion++;clearTimeout(teacherTimer);$('#demo-auto').checked=false;modelRunner?.stop();teacherAction(()=>classControl({ended:true}));}};
    $('#teacher-signout').onclick=()=>teacherAction(async()=>{await LiveCloud.teacherLogout();modelRunner?.stop();changeSession();role='entry';room=null;teacherStudents=[];selectedStudent=null;demoRun=null;$('#teacher-board').replaceChildren();$('#teacher-controls').replaceChildren();$('#teacher-controls').hidden=true;$('#teacher-model-tools').replaceChildren();$('#teacher-model-tools').hidden=true;$('#workspace').hidden=true;document.body.classList.remove('teacher-view');restorePupilNotebook();$('#student-name').value=notebook.name||'';$('#join').hidden=false;$('#teacher-login').hidden=true;$('#teacher-toggle').hidden=false;$('#export').hidden=false;$('.site-footer').hidden=false;notice('Signed out. Your separate student notebook has been preserved.');});
