    $('#teacher-model-tools').hidden=shareSafe||!editor;const note=$('#demo-step-note');if(note)note.textContent=matching?`Sharing to ${getStage(current)?.title}. Use my workspace code, then Share or Run and share. During Watch, students see the model instead of their editable workspace.`:'Bring class to this page before sharing a demonstration. You can rehearse privately in your workspace.';
