    $('#roster-summary').textContent=`${getStage(id)?.title||id} · ${attempted}/${students.length} with saved work. Open a card for the full response.`;
    if(room){const link=new URL(location.pathname,location.origin);link.searchParams.set('room',room.id);$('#invite-link').value=room.ended?'Room ended — start a new lesson':link.href;}else $('#invite-link').value='Start the lesson to create an invitation.';
